Definition stc_k (k : Z) : Z :=
  if k <? 10 then k else
  let n := k + 1 in
  let i := (28 - clz32 n) * 4 + 8 in
  let i := if size_class (i + 1) <? n then i + 2 else i in
  if size_class i <? n then i + 1 else i.
Lemma size_to_class_k n : size_to_class n = stc_k (Z.shiftr (n + IB - 1) 4).
