Fixpoint he_list (f : nat) (c : Z) : list Z :=
  match f with
  | O => [c]
  | S f' => c :: (if Z.even c then he_list f' (Z.shiftr c 1) else [])
  end.
Lemma halve_even_in f : forall c u, In (halve_even f c u) (he_list f c).
Proof.
