(* [comment removed for export] *)
Lemma clamp_ai size cnt : 1 <= cnt ->
  let ai := (4096 - UNIT) / size - 1 in
  let ai := if cnt - 1 <? ai then cnt - 1 else ai in
  let ai := if ai <? 0 then 0 else ai in
  0 <= ai <= cnt - 1.
Proof.
